var common_glsl = `
float hash( ivec3 i) { return fract(sin(float(i.x)*23.23+float(i.y)+float(i.z)*54.23)*17.2343); }
float sph( ivec3 i, vec3 f, ivec3 c )
{
   float rad = 0.5*hash(i+c);
   return length(f-vec3(c)) - rad;
}

float sdBase( vec3 p )
{
   ivec3 i = ivec3(floor(p));
    vec3 f =       fract(p);
   return min(min(min(sph(i,f,ivec3(0,0,0)),
                      sph(i,f,ivec3(0,0,1))),
                  min(sph(i,f,ivec3(0,1,0)),
                      sph(i,f,ivec3(0,1,1)))),
              min(min(sph(i,f,ivec3(1,0,0)),
                      sph(i,f,ivec3(1,0,1))),
                  min(sph(i,f,ivec3(1,1,0)),
                      sph(i,f,ivec3(1,1,1)))));
}
float hash1( float n ) { return fract(sin(n)*79127.2343); }
vec2 hash2( in vec2 x ) {
  int ii = int(mod(x.x+30.*x.y,Nrandf)); //counter into array of random #s
  int i2 = int(mod(x.y-30.*x.x,Nrandf)); //counter into array of random #s
  return vec2(rand[ii],rand[i2]);
}
float ddot ( in vec2 x, in vec2 y ) { return x.x+y.x + x.y*y.y; }
float dot3 ( in vec3 a, in vec3 b ) { return a.x*b.x + a.y*b.y + a.z*b.z; }
vec3 rot3d( in vec3 v, in vec3 k, in float theta) { // rotation of vector v about axis k, angle t with Rodrigues formula:
  return v*cos(theta)+cross(k,v)*sin(theta)+k*dot3(k,v)*(1.-cos(theta));
}
vec3 noise( in vec2 p ) {
    vec2 i = floor( p );
    vec2 f = fract( p );

    vec2 u = f*f*f*(f*(f*6.0-15.0)+10.0);
    vec2 du = 30.0*f*f*(f*(f-2.0)+1.0);

    vec2 ga = hash2( i + vec2(0.0,0.0) );
    vec2 gb = hash2( i + vec2(1.0,0.0) );
    vec2 gc = hash2( i + vec2(0.0,1.0) );
    vec2 gd = hash2( i + vec2(1.0,1.0) );

    float va = ddot( ga, f - vec2(0.0,0.0) );
    float vb = ddot( gb, f - vec2(1.0,0.0) );
    float vc = ddot( gc, f - vec2(0.0,1.0) );
    float vd = ddot( gd, f - vec2(1.0,1.0) );

    return vec3( va + u.x*(vb-va) + u.y*(vc-va) + u.x*u.y*(va-vb-vc+vd),   // value
                 ga + u.x*(gb-ga) + u.y*(gc-ga) + u.x*u.y*(ga-gb-gc+gd) +  // derivatives
                 du * (u.yx*(va-vb-vc+vd) + vec2(vb,vc) - va));
}

vec3 fbm( in vec2 x, in float H)
{
    float G = exp(-2.*H);
    float f = 1.0;
    float a = 1.0;
    vec3 t = vec3(0.0);
    for( int i=0; i<numOctaves; i++ )
    {
        t += a*noise(f*x);
        f *= 2.;
        a *= G;
    }
    return t;
}
float smooth_int( float d1, float d2, float k )
{
    float h = clamp( 0.5 - 0.5*(d2-d1)/k, 0.0, 1.0 );
    return mix( d2, d1, h ) + k*h*(1.0-h);
}
float smooth_union( float d1, float d2, float k )
{
    float h = clamp( 0.5 + 0.5*(d2-d1)/k, 0.0, 1.0 );
    return mix( d2, d1, h ) - k*h*(1.0-h);
}
float sgn( float x) { return (x<=0.) ? -1. : 1.; }
vec4 sdf(vec3 r, float t) {
  vec3 rr = r;
    vec3 r0 = vec3(0.5,-0.9,-2.);

r.y *= 1.+0.7*sin(kl[12]*0.2*r.x+kl[13]*0.14*r.z);
r.y -= 1.3; // r.y in (-1, 0)

// twist xz coords around y axis
 float k = 0.3*(kl[6]-.5);
float co = cos(k*r.y*cos(.01*t+kl[16]));
float si = sin(k*r.y*cos(.01*t+kl[17]));
mat2  m = mat2(co,-si,si,co);
vec2 xz = m*vec2(r.x,r.z);
r.x=xz.x;r.z=xz.y;

float dx = 0.7*(1.+kl[1]);
float c = 4./dx/dx;
float x = (fract(r.x/dx)-.5)*dx; // x in (-dx/2,dx/2)
float z = (fract(r.z/dx)-.5)*dx;
float yy = -r.y;
yy = mix(yy,2.-yy,kl[8]*kl[8]*(1.-kl[8]));
float ter = length(vec2(x,z))-0.2*kl[28];
r0.y = -1.;
ter += (.7+.6*kl[17])*(sdBase(r*(1.+.5*kl[23]))/(1.+.5*kl[23])+0.17*kl[20]);
k = 30.*kl[20];
if (kl[2]<0.1) {
  vec3 kk = noise(0.01*r.xz+0.01*sin(t+2.3));
  ter += (1.+kk.y)*2./k*max(0.,(r.y-r0.y))*(r.y-r0.y)*sin(k*(r.y-r0.y)*cos(kk.z*.5*k*r.y));
}
ter += 0.006*sin(t+cos(r.x)); //breathing
return vec4(ter,rr);
}
vec3 norm(vec3 p, float f, float dr, float t) {
    // sfc f(r)=0, inside f(r)<0. outward normal = grad f
    // f(r) = f(r-dr) + dr . grad f + ...
    // grad f.x = (f(r)-f(r-dx*(1,0,0)))/dx
    vec3 rp,n;
    rp = p - vec3(dr,0.,0.); n.x = f - sdf(rp,t).x;
    rp = p - vec3(0.,dr,0.); n.y = f - sdf(rp,t).x;
    rp = p - vec3(0.,0.,dr); n.z = f - sdf(rp,t).x;
    return normalize(n);
}
vec3 worldIntersect( vec3 p, vec3 ray, float maxlen, float t ) {
  vec3 r0 = p;
  bool coll = false;
  float d;
  vec4 dd;
  float dmin=maxlen;
  int i=0;
  while (i<60&&!coll) {
      dd = sdf(p,t); d=dd.x; //ter=dd.y;
      if (d > maxlen) break;
      dmin=min(dmin,d);
      if (d*(1.+d*smoothstep(0.,1.,clamp((kl[2]-.5)*p.y,0.,1.)))<0.0001) coll=true;
      p += ray*d*0.5;
      i++;
  }
  return vec3(length(p-ray*d*.5-r0),max(0.,dmin-0.00001),float(i));
}
float worldShadow( vec3 p, vec3 ray, float maxlen, float t, float k) {
  bool coll = false;
  float d; //,ter;
  vec4 dd;
  int i=0;
  float dmin=maxlen;
  float shad = 1.;
  float dist = 0.;
  for (int i=0; i<40&&!coll; i++) {
      //if (dot3(p,p) > maxlen*maxlen) break;
      dd = sdf(p,t); d=dd.x; //ter=dd.y;
      if (d > maxlen) break;
      dist += d;
      shad=min(shad,k*d/dist);
      if (d < 0.00001) coll = true;
      p += ray*d;
  }
  return shad;
}
float softShadow( vec3 p, vec3 ray, float maxlen, float t, float k) {
  bool coll = false;
  float d; //,ter;
  vec4 dd;
  int i=0;
  float dmin=maxlen;
  float shad = 1.;
  float dp = maxlen;
  float y,dist;
  for (int i=0; i<30&&!coll; i++) {
      dd = sdf(p,t); d=dd.x;
      if (d > maxlen) break;
      y = d*d/(2.*dp);
      dist = sqrt(d*d-y*y);
      shad=min(shad,k*dist/max(0.,d-y));
      if (d < 0.00001) coll = true;
      dp = d;
      p += ray*d;
  }
  return shad;
}
vec3 worldGetBackground( vec3 ray ) {
  return mix(vec3(0.4,0.2,0.1),vec3(0.1,.23,.7),smoothstep(-1.,1.,(-1.+2.*rand[42])*ray.y));
}
`;

