vec3 getray( vec3 p, vec3 n, vec3 ray) {
   vec3 perp = cross(ray,n);
   return rot3d(rot3d( ray, n , -1.57+3.14*hash1(2423.23*dot(p,n))), perp, kl[10]*(-0.2+0.4*hash1(2423423.23*ray.x)));
