vec3 render( vec3 p, vec3 ray, int N, float t )
{
    float maxlen = 30.;
    vec3 tcol = vec3(0.);
    vec3 fcol = vec3(1.);
    float dist = 0.;
    for (int i=0; i<N; i++) {
      // intersect scene
      vec3 v = worldIntersect( p, ray, maxlen, t );
      float d = v.x;
      dist+= d;
      // if nothing found, return background color
      if( d > maxlen )
         return worldGetBackground( ray );
      // get position and normal at the intersection point
      vec3 pos = p + ray*d;
      vec3 n = norm(pos,v.y,0.01,t);
      // get color for the surface
      vec3 scol = texture(pal, vec2(dot(ray,n),1./(1.+d))).rgb;
//      vec3 scol = worldGetColor( pos, n );
      // compute direct lighting
      vec3 dcol = worldApplyLighting( pos, n, maxlen, t);

      p = pos;
      ray = getray(pos,n,ray);

      // surface * lighting
      fcol *= scol;
      tcol += fcol * dcol;
    }
    tcol *= exp(-0.3*dist); // extinction
    return tcol;
  }


