  float tt = t; // + .6*(1./24.)*hash1(745345.123*uc.x+ifl+.5);
  p = r0;
  ray = cam*normalize(vec3((vv-.5)*vec2(res.x/res.y,1.),1.5));
  v = worldIntersect( p, ray, L, tt );
  if (kl[14]<0.3) v.z *= exp(2.*kl[14]);
  vec3 dp = ray*v.x*(.4+0.7*kl[6]); //*exp(-v.x);
  vec3 ray2 = reflect(ray,n); //-ray;
  float d = v.x;
  p+= d*ray;
